// clippy 1.99 flags the field init generated by the diesel QueryableByName derive.
#![allow(clippy::redundant_field_names)]

use crate::app::AppHandle;
use diesel::prelude::*;
use diesel::sqlite::SqliteConnection;
use tempfile::TempDir;

use super::{init_pool, test_pool, DbPool};

#[derive(diesel::QueryableByName)]
struct JournalMode {
    #[diesel(sql_type = diesel::sql_types::Text)]
    journal_mode: String,
}

/// Wires a real file-backed pool into a bare app handle so the tests below drive
/// the actual commands, state injection included.
pub(crate) fn test_app() -> (AppHandle, TempDir) {
    let directory = tempfile::tempdir().expect("temp dir");
    let app = AppHandle::default();
    app.manage(test_pool(&directory));
    (app, directory)
}

#[test]
fn opening_a_fresh_database_applies_migrations_and_enables_wal() {
    let (app, _directory) = test_app();
    let pool = app.state::<DbPool>();
    let mut connection = pool.get().expect("connection");

    let mode = diesel::sql_query("PRAGMA journal_mode")
        .get_result::<JournalMode>(&mut connection)
        .expect("read journal mode");
    assert_eq!(mode.journal_mode, "wal");

    let groups = orm::schema::connection_groups::table
        .count()
        .get_result::<i64>(&mut connection)
        .expect("migrated schema is queryable");
    assert_eq!(groups, 0);
}

#[tokio::test]
async fn settings_upsert_by_key_instead_of_piling_up_rows() {
    let (app, _directory) = test_app();

    for value in ["first", "second"] {
        super::settings::set_setting(
            shared::Setting {
                key: "noverdbee-config".to_string(),
                value: value.to_string(),
            },
            app.state(),
        )
        .await
        .expect("save setting");
    }

    let settings = super::settings::get_all_settings(app.state())
        .await
        .expect("list settings");
    assert_eq!(settings.len(), 1);
    assert_eq!(settings[0].value, "second");

    let single = super::settings::get_setting("noverdbee-config".to_string(), app.state())
        .await
        .expect("get setting");
    assert_eq!(
        single.map(|setting| setting.value).as_deref(),
        Some("second")
    );
}

#[tokio::test]
async fn saving_connections_makes_and_drops_their_groups() {
    let (app, _directory) = test_app();
    let save = |record: shared::DbConnectionRecord, group: &str| {
        super::connections::connection_save(record, group.to_string(), app.state())
    };
    let groups = || async {
        super::groups::group_list(app.state())
            .await
            .expect("list groups")
            .into_iter()
            .map(|group| group.name)
            .collect::<Vec<_>>()
    };
    let new = |name: &str| shared::DbConnectionRecord {
        name: name.to_string(),
        driver: "postgres".to_string(),
        password: "secret".to_string(),
        ..Default::default()
    };

    let orders = save(new(" orders "), " production ").await.expect("create");
    let billing = save(new("billing"), "production").await.expect("create");
    assert_eq!(orders.name, "orders");
    assert_eq!(orders.group_id, billing.group_id, "one group per name");
    assert_eq!(groups().await, ["production"]);
    assert!(save(new("  "), "").await.is_err(), "a name is required");

    let moved = save(
        shared::DbConnectionRecord {
            name: "orders-ro".to_string(),
            read_only: true,
            environment: shared::Environment::Production,
            ..orders.clone()
        },
        "staging",
    )
    .await
    .expect("update");
    assert_eq!(moved.id, orders.id);
    assert_eq!(groups().await, ["production", "staging"]);

    let ungrouped = save(billing.clone(), "").await.expect("ungroup");
    assert_eq!(ungrouped.group_id, None);
    assert_eq!(groups().await, ["staging"], "an empty group goes away");

    let listed = super::connections::connection_list(app.state())
        .await
        .expect("list connections");
    let names: Vec<&str> = listed.iter().map(|row| row.name.as_str()).collect();
    assert_eq!(names, ["billing", "orders-ro"], "updates must not add rows");
    assert!(listed[1].read_only);
    assert_eq!(listed[1].environment, shared::Environment::Production);
    assert_eq!(listed[0].environment, shared::Environment::Development);
    assert_eq!(listed[1].password, "secret");

    super::connections::connection_delete(orders.id, app.state())
        .await
        .expect("delete connection");
    assert!(groups().await.is_empty());
}

#[tokio::test]
async fn a_restored_backup_replaces_the_database_on_next_launch() {
    let directory = tempfile::tempdir().expect("temp dir");
    let database = directory.path().join("noverdbee.db");
    let backup = directory.path().join("backup.db");
    let save = |path: &std::path::Path, value: &str| {
        let pool = init_pool(path).expect("open database");
        let app = AppHandle::default();
        app.manage(pool);
        let setting = shared::Setting {
            key: "marker".to_string(),
            value: value.to_string(),
        };
        async move { super::settings::set_setting(setting, app.state()).await }
    };
    save(&backup, "backup").await.expect("save backup");
    save(&database, "current").await.expect("save current");

    let junk = directory.path().join("junk.db");
    std::fs::write(&junk, "not a database").expect("write junk");
    assert!(super::stage_restore(&junk, &database).is_err());
    assert!(super::check_backup(&foreign_database(&directory)).is_err());

    super::stage_restore(&backup, &database).expect("stage restore");
    super::apply_pending_restore(&database).expect("apply restore");

    let read = |path: std::path::PathBuf| async move {
        let app = AppHandle::default();
        app.manage(init_pool(&path).expect("open database"));
        super::settings::get_setting("marker".to_string(), app.state())
            .await
            .expect("get setting")
            .map(|setting| setting.value)
    };
    assert_eq!(read(database.clone()).await.as_deref(), Some("backup"));
    let previous = directory.path().join("noverdbee.db.before-restore");
    assert_eq!(read(previous).await.as_deref(), Some("current"));
    // Nothing is left staged, so the next launch does not restore again.
    assert!(!directory.path().join("noverdbee.db.restore").exists());
}

/// An empty SQLite database: valid, but not one of ours.
fn foreign_database(directory: &TempDir) -> std::path::PathBuf {
    use diesel::connection::SimpleConnection as _;
    let path = directory.path().join("other.db");
    SqliteConnection::establish(&path.to_string_lossy())
        .expect("create database")
        .batch_execute("CREATE TABLE t (x)")
        .expect("create table");
    path
}

#[test]
fn connections_take_their_environment_from_the_group_they_were_in() {
    use diesel::connection::SimpleConnection;
    use diesel::migration::MigrationSource;
    use diesel_migrations::MigrationHarness;

    let mut connection = SqliteConnection::establish(":memory:").expect("memory db");
    let before = MigrationSource::<diesel::sqlite::Sqlite>::migrations(&super::MIGRATIONS)
        .expect("list")
        .iter()
        .position(|migration| {
            migration
                .name()
                .to_string()
                .ends_with("connection_environment")
        })
        .expect("the environment migration");
    // Every migration before the environment one.
    for _ in 0..before {
        connection
            .run_next_migration(super::MIGRATIONS)
            .expect("earlier migration");
    }
    connection
        .batch_execute(
            "INSERT INTO connection_groups (id, name) VALUES ('p', 'Prod EU'), ('s', 'staging'), ('c', 'client-a');
         INSERT INTO db_connections (id, name, driver, group_id) VALUES
           ('1', 'a', 'sqlite', 'p'), ('2', 'b', 'sqlite', 's'),
           ('3', 'c', 'sqlite', 'c'), ('4', 'd', 'sqlite', NULL);",
        )
        .expect("seed");
    connection
        .run_next_migration(super::MIGRATIONS)
        .expect("environment migration");

    let environments: Vec<String> = orm::schema::db_connections::table
        .order(orm::schema::db_connections::id)
        .select(orm::schema::db_connections::environment)
        .load(&mut connection)
        .expect("read environments");
    assert_eq!(
        environments,
        ["production", "staging", "development", "development"]
    );
}

#[tokio::test]
async fn a_group_renames_merges_into_a_namesake_and_dissolves() {
    let (app, _directory) = test_app();
    let save = |name: &str, group: &str| {
        super::connections::connection_save(
            shared::DbConnectionRecord {
                name: name.to_string(),
                driver: "sqlite".to_string(),
                ..Default::default()
            },
            group.to_string(),
            app.state(),
        )
    };
    let groups = || async {
        super::groups::group_list(app.state())
            .await
            .expect("list groups")
    };
    let a = save("a", "shop").await.expect("save");
    save("b", "billing").await.expect("save");
    let shop = a.group_id.clone().expect("in a group");

    super::groups::group_rename(shop.clone(), " store ".to_string(), app.state())
        .await
        .expect("rename");
    let names: Vec<String> = groups().await.into_iter().map(|group| group.name).collect();
    assert_eq!(names, ["billing", "store"]);
    assert!(
        super::groups::group_rename(shop.clone(), " ".to_string(), app.state())
            .await
            .is_err()
    );

    super::groups::group_rename(shop, "billing".to_string(), app.state())
        .await
        .expect("merge");
    let listed = groups().await;
    assert_eq!(listed.len(), 1, "the renamed group joined billing");
    let billing = listed[0].id.clone();
    let connections = super::connections::connection_list(app.state())
        .await
        .expect("list");
    assert!(connections
        .iter()
        .all(|row| row.group_id.as_deref() == Some(billing.as_str())));

    super::groups::group_dissolve(billing, app.state())
        .await
        .expect("dissolve");
    assert!(groups().await.is_empty());
    let connections = super::connections::connection_list(app.state())
        .await
        .expect("list");
    assert_eq!(connections.len(), 2, "dissolving keeps the connections");
    assert!(connections.iter().all(|row| row.group_id.is_none()));
}

#[tokio::test]
async fn history_keeps_one_entry_per_sql_newest_first() {
    let (app, _directory) = test_app();
    let record = super::connections::connection_save(
        shared::DbConnectionRecord {
            name: "shop".to_string(),
            driver: "sqlite".to_string(),
            ..Default::default()
        },
        String::new(),
        app.state(),
    )
    .await
    .expect("save");
    let add =
        |sql: &str| super::history::history_add(record.id.clone(), sql.to_string(), app.state());
    let list = || async {
        super::history::history_list(record.id.clone(), app.state())
            .await
            .expect("list")
            .into_iter()
            .map(|entry| entry.sql)
            .collect::<Vec<_>>()
    };

    add("SELECT 1").await.expect("add");
    add("  ").await.expect("blank is skipped");
    add("SELECT 2").await.expect("add");
    add(" SELECT 1 ").await.expect("again");
    assert_eq!(list().await, ["SELECT 1", "SELECT 2"]);

    super::connections::connection_delete(record.id.clone(), app.state())
        .await
        .expect("delete");
    assert!(list().await.is_empty(), "history goes with its connection");
}

#[tokio::test]
async fn a_connection_signs_in_with_its_saved_host_key_and_kubeconfig() {
    use super::tunnels;
    let (app, _directory) = test_app();

    let refused = tunnels::ssh_key_save(
        shared::SshKeyRecord {
            name: "deploy".to_string(),
            private_key: "not a key".to_string(),
            ..Default::default()
        },
        app.state(),
    )
    .await
    .expect_err("not a key");
    assert!(
        refused.starts_with("cannot read the SSH key: "),
        "{refused}"
    );
    let key = tunnels::ssh_key_save(
        shared::SshKeyRecord {
            name: "deploy".to_string(),
            private_key: TEST_KEY.to_string(),
            ..Default::default()
        },
        app.state(),
    )
    .await
    .expect("save key");
    assert!(
        key.fingerprint.starts_with("SHA256:"),
        "{}",
        key.fingerprint
    );

    let host = tunnels::ssh_host_save(
        shared::SshHostRecord {
            name: " bastion ".to_string(),
            host: "bastion.example.com".to_string(),
            port: 22,
            username: "ubuntu".to_string(),
            password: "secret".to_string(),
            ..Default::default()
        },
        app.state(),
    )
    .await
    .expect("save host");
    assert_eq!(host.name, "bastion");
    let kubeconfig = tunnels::kubeconfig_save(
        shared::KubeconfigRecord {
            name: "staging".to_string(),
            config: "apiVersion: v1\nkind: Config\n".to_string(),
            ..Default::default()
        },
        app.state(),
    )
    .await
    .expect("save kubeconfig");

    super::connections::connection_save(
        shared::DbConnectionRecord {
            name: "orders".to_string(),
            driver: "postgres".to_string(),
            tunnel: "ssh".to_string(),
            ssh_host_id: Some(host.id.clone()),
            kubeconfig_id: Some(kubeconfig.id.clone()),
            ..Default::default()
        },
        String::new(),
        app.state(),
    )
    .await
    .expect("save connection");
    let load = || async {
        super::connections::connection_list(app.state())
            .await
            .expect("list")
            .remove(0)
    };
    let loaded = load().await;
    let login = loaded.ssh.expect("the saved host");
    assert_eq!(
        (login.host.as_str(), login.password.as_str()),
        ("bastion.example.com", "secret")
    );
    assert_eq!(loaded.kube_config, "apiVersion: v1\nkind: Config\n");

    // Deleting what a connection points at leaves the connection, unpicked.
    tunnels::ssh_host_delete(host.id, app.state())
        .await
        .expect("delete host");
    tunnels::kubeconfig_delete(kubeconfig.id, app.state())
        .await
        .expect("delete kubeconfig");
    let loaded = load().await;
    assert_eq!((loaded.ssh_host_id, loaded.kubeconfig_id), (None, None));
    assert_eq!((loaded.ssh, loaded.kube_config), (None, String::new()));
}

